content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-009

=== 用户原始指令 (query.txt) ===
搞个内存清理的 按钮点一下能进去操作 然后有红色提示那种

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个内存清理的 按钮点一下能进去操作 然后有红色提示那种",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "memory": {
        "title": {
          "type": "string",
          "description": "内存清理卡片标题",
          "sampleValue": "内存清理"
        },
        "usedPercent": {
          "type": "number",
          "description": "当前内存占用百分比数值，用于进度环",
          "sampleValue": 83
        },
        "usedPercentText": {
          "type": "string",
          "description": "当前内存占用百分比展示文本",
          "sampleValue": "83%"
        },
        "usedLabel": {
          "type": "string",
          "description": "内存占用指标说明",
          "sampleValue": "内存已用"
        },
        "reclaimText": {
          "type": "string",
          "description": "预计可释放内存说明",
          "sampleValue": "可清理 1.8GB"
        },
        "alertText": {
          "type": "string",
          "description": "红色状态提示文案",
          "sampleValue": "红色提示"
        },
        "hintText": {
          "type": "string",
          "description": "清理操作的辅助说明",
          "sampleValue": "释放后台占用"
        },
        "actionText": {
          "type": "string",
          "description": "进入清理操作的按钮文案",
          "sampleValue": "去清理"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标，适合表达内存清理、垃圾清除和清理无忧入口。"
    }
  ]
}

